/**
 * @summary Sets styles for trial header bar
 * @name header
 * @selector .slds-trial-header
 * @restrict div
 * @support dev-ready
 * @variant
 */
.slds-trial-header {
  @include inverse-text($support: ('buttons', 'icons'));
  height: $height-header;
  background: var(--slds-g-color-brand-base-10, #{$color-background-inverse});
  padding: 0 $spacing-medium;

  .slds-icon_selected,
  .slds-icon--selected {
    fill: var(--slds-g-color-success-base-70, #{$color-text-success-inverse});
  }

  button:not([class*=slds-button_]):not([class*=slds-button--]):focus {
    box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
  }
}
